use xiom.io;

type Song = {
  title: Str;
  artist: Str;
  duration_sec: Int;
}

fn Song.format(self) -> Str {
  let mins = duration_sec / 60;
  let secs = duration_sec % 60;
  return "\"" + title + "\" by " + artist + " (" + mins + ":" + secs + ")";
}

fn total_runtime(a: Song, b: Song, c: Song) -> Int {
  return a.duration_sec + b.duration_sec + c.duration_sec;
}

fn main() -> Int {
  let s1 = Song{ title: "Neon Lights"; artist: "Synthwave Kid"; duration_sec: 217; };
  let s2 = Song{ title: "Midnight Drive"; artist: "Synthwave Kid"; duration_sec: 194; };
  let s3 = Song{ title: "Stargazer"; artist: "Cosmic Beats"; duration_sec: 245; };
  return total_runtime(s1, s2, s3);
}
